#include <Arduino.h>
void fastTask(void*) { for (;;) { Serial.println("fast task"); vTaskDelay(pdMS_TO_TICKS(300)); } }
void slowTask(void*) { for (;;) { Serial.println("slow task"); vTaskDelay(pdMS_TO_TICKS(1000)); } }
void setup() { Serial.begin(115200); if (xTaskCreate(fastTask, "fast", 2048, nullptr, 1, nullptr) != pdPASS) Serial.println("fast task creation failed"); if (xTaskCreate(slowTask, "slow", 2048, nullptr, 1, nullptr) != pdPASS) Serial.println("slow task creation failed"); }
void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }

#include <Arduino.h>
void sensorTask(void*) { for (;;) { Serial.println("sample"); vTaskDelay(pdMS_TO_TICKS(500)); } }
void setup() { Serial.begin(115200); xTaskCreate(sensorTask, "sensor", 2048, nullptr, 1, nullptr); }
void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }
